"""The book file: a SQLite database with numbered schema versions."""
import json
import os
import re
import sqlite3
from contextlib import contextmanager
from dataclasses import dataclass, field, replace
from datetime import date, timedelta

from tallybook import budgets as _budgets
from tallybook import csvimport as _csvimport
from tallybook import recurring as _recurring
from tallybook.accounts import TYPES, Chart, ChartError
from tallybook.currency import CurrencyError, RateTable, currency
from tallybook.dates import format_date, is_date, parse_date
from tallybook.errors import ConflictError, NotFoundError, ValidationError
from tallybook.export import money_to_dict, transaction_to_dict, transactions_from_json
from tallybook.journal import Journal
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money
from tallybook.query import Query, parse_query
from tallybook.rules import RuleSet, parse_rules

LATEST_VERSION = 4

_PROFILE_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NAME_CHARS = re.compile(r"[A-Za-z0-9_-]+")
_LETTERS3 = re.compile(r"[A-Za-z]{3}")
_MAX_MINOR = 2**63 - 1


@dataclass
class BulkAdd:
    added: list = field(default_factory=list)
    skipped: list = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: list = field(default_factory=list)
    duplicates: list = field(default_factory=list)
    errors: list = field(default_factory=list)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


# -- schema steps -------------------------------------------------------------
                pass

    # -- plumbing ---------------------------------------------------------
    def _alive(self):
        if self._closed:
            raise ConflictError("the book is closed")

    @property
    def version(self):
        self._alive()
        return self._conn.execute("PRAGMA user_version").fetchone()[0]

    def _current(self):
        self._alive()
        version = self.version
        if version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)

    @contextmanager
    def _write(self):
        self._current()
        conn = self._conn
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.Error as exc:
            raise ConflictError("database is busy: %s" % exc) from None
        try:
            yield conn
        except sqlite3.Error as exc:
            self._rollback()
            raise ConflictError("database error: %s" % exc) from None
        except BaseException:
            self._rollback()
            raise
        else:
            try:
                conn.execute("COMMIT")
            except sqlite3.Error as exc:
                self._rollback()
                raise ConflictError("database is busy: %s" % exc) from None

    def _rollback(self):
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass

    @contextmanager
    def _read(self):
        self._current()
        conn = self._conn
        try:
            conn.execute("BEGIN")
        except sqlite3.Error as exc:
            raise ConflictError("database is busy: %s" % exc) from None
        try:
            yield conn
        except sqlite3.Error as exc:
            raise ConflictError("database error: %s" % exc) from None
        finally:
            self._rollback()

    # -- migrations -------------------------------------------------------
    def has_import_key(self, key):
        with self._read():
            return self._conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone() is not None

    def _get_tx(self, id):
        if not _is_int(id):
            raise NotFoundError("no transaction %s" % (id,))
        rows = self._tx_rows("WHERE id = ?", (id,))
        if not rows:
            raise NotFoundError("no transaction %s" % id)
        return self._assemble(rows)[0]

    def get_transaction(self, id):
        with self._read():
            return self._get_tx(id)

    def delete_transaction(self, id):
        with self._write() as conn:
            tx = self._get_tx(id)
            for table in ("import_keys", "tags", "postings"):
                conn.execute("DELETE FROM %s WHERE tx_id = ?" % table, (id,))
            conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
            return tx

    @staticmethod
    def _check_minor(amount, what="amount"):
        minor = amount.minor
        if -_MAX_MINOR - 1 <= minor <= _MAX_MINOR:
            return
        if minor.bit_length() <= 128:
            shown = "%d %s minor units" % (minor, amount.currency)
        else:
            shown = "of about %d digits (%s minor units)" % (int(minor.bit_length() * 0.30103) + 1, amount.currency)
        raise ValidationError("%s %s is too large for the book file (limit %d minor units)" % (what, shown, _MAX_MINOR))

    def _insert(self, conn, tx):
        for p in tx.postings:
            self._check_minor(p.amount, "posting amount")
        cur = conn.execute(
            "INSERT INTO transactions(date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
            (format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0, tx.flag),
        )
        tid = cur.lastrowid
        for seq, p in enumerate(tx.postings):
            conn.execute(
                "INSERT INTO postings(tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                (tid, seq, p.account, p.amount.minor, p.amount.currency, p.note),
            )
        for tag in tx.tags:
            conn.execute("INSERT INTO tags(tx_id, tag) VALUES (?, ?)", (tid, tag))
        return replace(tx, id=tid)

    def _validated(self, ledger, tx):
        if isinstance(tx, Transaction):
            tx = replace(tx, id=None)
        return ledger.add(tx)

    def add_transaction(self, tx):
        with self._write() as conn:
            ledger = Ledger(self._chart(), self._rate_table())
            return self._insert(conn, self._validated(ledger, tx))

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or any(not isinstance(k, str) for k in keys):
                raise ValidationError("keys must hold one text per transaction")
        result = BulkAdd()
        with self._write() as conn:
            ledger = Ledger(self._chart(), self._rate_table())
            seen = set()
            for index, tx in enumerate(txs):
                key = None if keys is None else keys[index]
                if key is not None and (
                    key in seen or conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone()
                ):
                    result.skipped.append(index)
                    continue
                try:
                    stored = self._insert(conn, self._validated(ledger, tx))
                except ValidationError as exc:
                    exc.detail = dict(exc.detail, index=index)
                    raise
                if key is not None:
                    seen.add(key)
                    conn.execute("INSERT INTO import_keys(key, tx_id) VALUES (?, ?)", (key, stored.id))
                result.added.append(stored)
        return result

    def ledger(self):
        with self._read():
            ledger = Ledger(self._chart(), self._rate_table())
            for tx in self._assemble(self._tx_rows()):
                ledger.add(tx)
            return ledger

    # -- rates, budgets, recurring ----------------------------------------
            return [rec for rec, _ in self._recurring_rows()]

    def materialized_through(self, name):
        with self._read():
            row = self._conn.execute("SELECT materialized_through FROM recurring WHERE name = ?", (name,)).fetchone()
            if row is None:
                raise NotFoundError("no recurring item %s" % (name,))
            return parse_date(row[0]) if row[0] else None

    def materialize(self, upto=None, today=None):
        for value in (upto, today):
            if value is not None and not is_date(value):
                raise ValidationError("horizon must be a date, got %r" % (value,))
        if upto is None and today is None:
            raise ValidationError("materialize needs upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        with self._write() as conn:
            items = self._recurring_rows()
            pending = []
            for rec, through in items:
                first = rec.start if through is None else max(rec.start, through + timedelta(days=1))
                if first > horizon:
                    continue
                for d in _recurring.occurrences(rec, first, horizon):
                    pending.append((d, rec.name, _recurring.instantiate(rec, d)))
            pending.sort(key=lambda item: (item[0], item[1]))
            ledger = Ledger(self._chart(), self._rate_table())
            made = []
            for index, (_, _, tx) in enumerate(pending):
                try:
                    made.append(self._insert(conn, self._validated(ledger, tx)))
                except ValidationError as exc:
                    exc.detail = dict(exc.detail, index=index)
                    raise
            for rec, through in items:
                if through is None or horizon > through:
                    conn.execute(
                        "UPDATE recurring SET materialized_through = ? WHERE name = ?", (format_date(horizon), rec.name)
                    )
            return made

    # -- rules, settings, profiles ---------------------------------------
    def set_rules(self, text):
        if not isinstance(text, str):
            raise ValidationError("rules must be text")
        parse_rules(text)
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO rules(id, body) VALUES (1, ?)", (text,))

    def _rules_text(self):
        row = self._conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
        return "" if row is None else row[0]

    def rules_text(self):
        with self._read():
            return self._rules_text()

    def rules(self):
        return parse_rules(self.rules_text())

    def get_setting(self, key, default=None):
        with self._read():
            row = self._conn.execute("SELECT value FROM settings WHERE key = ?", (key,)).fetchone()
            return default if row is None else row[0]

    def set_setting(self, key, value):
